import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Search, PlaneTakeoff, Trash2, List, Grid, MoreHorizontal, ChevronLeft, ChevronRight } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

export default function FileList({ onViewChange }) {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedFiles, setSelectedFiles] = useState(new Set());
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: files = [], isLoading } = useQuery({
    queryKey: ["/api/files"],
  });

  const deleteMutation = useMutation({
    mutationFn: async (fileId) => {
      return apiRequest("DELETE", `/api/files/${fileId}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["/api/files"]);
      toast({
        title: "Success",
        description: "File deleted successfully",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to delete file",
        variant: "destructive",
      });
    },
  });

  const filteredFiles = files.filter(file =>
    file.title.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleSelectAll = (checked) => {
    if (checked) {
      setSelectedFiles(new Set(filteredFiles.map(f => f.id)));
    } else {
      setSelectedFiles(new Set());
    }
  };

  const handleSelectFile = (fileId, checked) => {
    const newSelected = new Set(selectedFiles);
    if (checked) {
      newSelected.add(fileId);
    } else {
      newSelected.delete(fileId);
    }
    setSelectedFiles(newSelected);
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  if (isLoading) {
    return (
      <div className="h-full p-6 flex items-center justify-center">
        <div className="text-muted-foreground">Loading files...</div>
      </div>
    );
  }

  return (
    <div className="h-full p-6">
      <div className="h-full flex flex-col">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center space-x-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground w-4 h-4" />
              <input 
                type="text" 
                placeholder="Search by Name"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="bg-input border border-border rounded-lg pl-10 pr-4 py-2 text-foreground placeholder-muted-foreground w-64"
                data-testid="input-search-list"
              />
            </div>
          </div>
          <div className="flex items-center space-x-4">
            <button 
              className="bg-primary text-primary-foreground px-4 py-2 rounded-lg hover:bg-primary/90 transition-colors"
              data-testid="button-send-list"
            >
              <PlaneTakeoff className="mr-2 w-4 h-4" />
              SEND
            </button>
            <button 
              className="bg-secondary text-secondary-foreground px-4 py-2 rounded-lg hover:bg-secondary/90 transition-colors border border-border"
              data-testid="button-delete-list"
            >
              <Trash2 className="mr-2 w-4 h-4" />
              DELETE
            </button>
            <button 
              onClick={() => onViewChange('content-grid')}
              className="p-2 border border-border rounded hover:bg-secondary transition-colors"
              data-testid="button-grid-view-switch"
            >
              <Grid className="w-4 h-4" />
            </button>
            <button className="p-2 border border-border rounded bg-secondary" data-testid="button-list-view-active">
              <List className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div className="bg-card rounded-lg border border-border overflow-hidden flex-1 flex flex-col">
          {/* Table Header */}
          <div className="grid grid-cols-12 gap-4 p-4 border-b border-border bg-secondary text-sm font-medium">
            <div className="col-span-1">
              <input 
                type="checkbox" 
                className="text-primary"
                checked={selectedFiles.size === filteredFiles.length && filteredFiles.length > 0}
                onChange={(e) => handleSelectAll(e.target.checked)}
                data-testid="checkbox-select-all"
              />
            </div>
            <div className="col-span-1">Thumbnail</div>
            <div className="col-span-3">Title</div>
            <div className="col-span-2">Uploaded</div>
            <div className="col-span-2">Type</div>
            <div className="col-span-2">Size</div>
            <div className="col-span-1">Actions</div>
          </div>

          {/* Table Rows */}
          <div className="flex-1 overflow-y-auto">
            {filteredFiles.map((file) => (
              <div 
                key={file.id} 
                className="grid grid-cols-12 gap-4 p-4 border-b border-border hover:bg-secondary/50 transition-colors"
                data-testid={`file-row-${file.id}`}
              >
                <div className="col-span-1">
                  <input 
                    type="checkbox" 
                    className="text-primary"
                    checked={selectedFiles.has(file.id)}
                    onChange={(e) => handleSelectFile(file.id, e.target.checked)}
                    data-testid={`checkbox-${file.id}`}
                  />
                </div>
                <div className="col-span-1">
                  <img 
                    src={file.thumbnailUrl}
                    alt={`${file.title} thumbnail`}
                    className="w-12 h-9 object-cover rounded"
                  />
                </div>
                <div className="col-span-3">
                  <div className="font-medium" data-testid={`file-title-list-${file.id}`}>{file.title}</div>
                </div>
                <div className="col-span-2 text-muted-foreground text-sm">
                  {formatDate(file.uploadDate)}
                </div>
                <div className="col-span-2 text-muted-foreground text-sm">
                  {file.type}
                </div>
                <div className="col-span-2 text-muted-foreground text-sm">
                  {formatFileSize(file.size)}
                </div>
                <div className="col-span-1">
                  <button 
                    className="text-muted-foreground hover:text-foreground"
                    data-testid={`button-actions-${file.id}`}
                  >
                    <MoreHorizontal className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>

          {filteredFiles.length === 0 && (
            <div className="flex-1 flex items-center justify-center text-muted-foreground" data-testid="empty-state-list">
              No files found
            </div>
          )}

          {/* Pagination */}
          <div className="flex justify-between items-center p-4 border-t border-border bg-secondary/30">
            <div className="text-sm text-muted-foreground" data-testid="pagination-info">
              Records per page: 15 <span className="ml-4">15 of {filteredFiles.length}</span>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                className="p-2 text-muted-foreground hover:text-foreground disabled:opacity-50" 
                disabled
                data-testid="button-prev-page"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
              <button 
                className="p-2 text-muted-foreground hover:text-foreground"
                data-testid="button-next-page"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/components/file-upload.jsx.content:
import { useState, useRef } from "react";
import { CloudUpload, PlaneTakeoff } from "lucide-react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

export default function FileUpload() {
  const [sendMethod, setSendMethod] = useState("email");
  const [emails, setEmails] = useState("");
  const [packageOption, setPackageOption] = useState("");
  const [destination, setDestination] = useState("");
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const uploadMutation = useMutation({
    mutationFn: async (fileData) => {
      return apiRequest("POST", "/api/files", fileData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["/api/files"]);
      toast({
        title: "Success",
        description: "File uploaded successfully",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: "Failed to upload file",
        variant: "destructive",
      });
    },
  });

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragOver(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragOver(false);
    const files = Array.from(e.dataTransfer.files);
    handleFiles(files);
  };

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files);
    handleFiles(files);
  };

  const handleFiles = (files) => {
    files.forEach(file => {
      const fileData = {
        userId: "demo-user-id",
        title: file.name.split('.')[0],
        filename: file.name,
        size: file.size,
        type: file.type.split('/')[1]?.toUpperCase() || 'UNKNOWN',
        thumbnailUrl: file.type.startsWith('image/') ? URL.createObjectURL(file) : null,
        isPublic: false,
      };

      uploadMutation.mutate(fileData);
    });
  };

  const handleSend = () => {
    if (!emails.trim() && sendMethod === "email") {
      toast({
        title: "Error",
        description: "Please enter recipient emails",
        variant: "destructive",
      });
      return;
    }

    toast({
      title: "Success",
      description: "Files sent successfully",
    });
  };

  return (
    <div className="h-full p-6">
      <div className="h-full flex flex-col">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold" data-testid="upload-title">Upload Files</h1>
          <div className="flex items-center space-x-4">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="bg-primary text-primary-foreground px-4 py-2 rounded-lg hover:bg-primary/90 transition-colors"
              data-testid="button-add-files"
            >
              Add Files
            </button>
            <button 
              className="bg-secondary text-secondary-foreground px-4 py-2 rounded-lg hover:bg-secondary/90 transition-colors border border-border"
              data-testid="button-add-folders"
            >
              Add Folders
            </button>
          </div>
        </div>

        <input
          ref={fileInputRef}
          type="file"
          multiple
          onChange={handleFileSelect}
          className="hidden"
          data-testid="file-input"
        />

        <div 
          className={`upload-zone flex-1 rounded-lg flex flex-col items-center justify-center p-12 mb-6 cursor-pointer ${
            isDragOver ? "drag-over" : ""
          }`}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
          data-testid="upload-zone"
        >
          <div className="text-center">
            <CloudUpload className="text-6xl text-muted-foreground mb-6 w-16 h-16 mx-auto" />
            <h3 className="text-xl font-semibold mb-2">Drag and Drop here</h3>
            <p className="text-muted-foreground mb-4">Accepts all file formats and preserves folder structures</p>
            <div className="text-sm text-muted-foreground">Maximum of 30 recipients</div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <h4 className="font-semibold mb-4">Send Options</h4>
            <div className="space-y-3">
              <label className="flex items-center" data-testid="send-method-email">
                <input 
                  type="radio" 
                  name="sendMethod" 
                  value="email"
                  checked={sendMethod === "email"}
                  onChange={(e) => setSendMethod(e.target.value)}
                  className="mr-3 text-primary"
                />
                <span>Send link via email</span>
              </label>
              <label className="flex items-center" data-testid="send-method-link">
                <input 
                  type="radio" 
                  name="sendMethod" 
                  value="link"
                  checked={sendMethod === "link"}
                  onChange={(e) => setSendMethod(e.target.value)}
                  className="mr-3 text-primary"
                />
                <span>Generate Shareable link</span>
              </label>
            </div>

            <div className="mt-4">
              <label className="block text-sm font-medium mb-2">Members</label>
              <textarea 
                placeholder="Enter Emails" 
                value={emails}
                onChange={(e) => setEmails(e.target.value)}
                className="w-full bg-input border border-border rounded-lg p-3 text-foreground placeholder-muted-foreground resize-none"
                rows="4"
                data-testid="textarea-emails"
              />
            </div>
          </div>

          <div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Package Options</label>
                <select 
                  value={packageOption}
                  onChange={(e) => setPackageOption(e.target.value)}
                  className="w-full bg-input border border-border rounded-lg p-3 text-foreground"
                  data-testid="select-package"
                >
                  <option value="">Select...</option>
                  <option value="zip">ZIP Archive</option>
                  <option value="individual">Individual Files</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Destinations</label>
                <select 
                  value={destination}
                  onChange={(e) => setDestination(e.target.value)}
                  className="w-full bg-input border border-border rounded-lg p-3 text-foreground"
                  data-testid="select-destination"
                >
                  <option value="">Select...</option>
                  <option value="cloud">Cloud Storage</option>
                  <option value="direct">Direct Download</option>
                </select>
              </div>
            </div>

            <button 
              onClick={handleSend}
              disabled={uploadMutation.isPending}
              className="w-full bg-primary text-primary-foreground py-3 rounded-lg font-semibold hover:bg-primary/90 transition-colors mt-6 disabled:opacity-50"
              data-testid="button-send"
            >
              <PlaneTakeoff className="mr-2 w-4 h-4 inline" />
              {uploadMutation.isPending ? "SENDING..." : "SEND"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

